import{_ as a,o as i,c as t,a2 as r}from"./chunks/framework.iXqqCa-C.js";const s="/images/misskey-reaction-picker.webp",m=JSON.parse('{"title":"回应与表情符号","description":"","frontmatter":{},"headers":[],"relativePath":"guide/misskey/reactions.md","filePath":"guide/misskey/reactions.md","lastUpdated":1793501934000}'),o={name:"guide/misskey/reactions.md"};function l(n,e,c,d,p,h){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="回应与表情符号" tabindex="-1">回应与表情符号 <a class="header-anchor" href="#回应与表情符号" aria-label="Permalink to &quot;回应与表情符号&quot;">​</a></h1><h2 id="回应" tabindex="-1">回应 <a class="header-anchor" href="#回应" aria-label="Permalink to &quot;回应&quot;">​</a></h2><p>回应（Reaction）是用任意表情回应帖子的互动方式，如 😂 😭 👍 ❤️ 或服务器的自定义表情。</p><ul><li>点击帖子下方的 <strong>+</strong> 打开回应选择器，选一个表情即可回应。</li><li>点击帖子已有的回应可以查看回应者列表，再点一次自己发出的回应即可取消。</li></ul><h2 id="回应相关的设置" tabindex="-1">回应相关的设置 <a class="header-anchor" href="#回应相关的设置" aria-label="Permalink to &quot;回应相关的设置&quot;">​</a></h2><ul><li><strong>将回应设置为公开</strong>（设置 → 隐私）：他人可以在你主页的「回应」标签看到你发出的回应。</li><li><strong>接受表情回应</strong>（设置 → 个人资料）：限制别人在你的帖子上可用的回应。</li></ul><p>两项的完整说明见<a href="/guide/misskey/settings-privacy">设置与隐私</a>。</p><h2 id="表情符号调色板" tabindex="-1">表情符号调色板 <a class="header-anchor" href="#表情符号调色板" aria-label="Permalink to &quot;表情符号调色板&quot;">​</a></h2><p>发帖或回应时弹出的表情选择器：</p><ul><li>包含 Unicode 表情和服务器自定义表情（<code>:名字:</code> 格式）。</li><li>在「设置 → 表情符号调色板」可以创建多个调色板，分别指定回应和发帖使用的调色板，并调整选择器的显示方式（弹出 / 抽屉）、大小和列数。</li></ul><p><img src="'+s+'" alt="回应选择器"></p><p>相关页面：<a href="/guide/posts#互动">帖子互动</a>、<a href="/guide/misskey/mfm">MFM 语法</a>。</p>',12)])])}const _=a(o,[["render",l]]);export{m as __pageData,_ as default};
